// Offline cache for Jamyang Dzongsar Construction. Generated by build.py; do not edit.
const CACHE = 'sitebook-8290fa3694';
const FILES = ["./", "index.html", "manifest.webmanifest", "fonts.css", "Barlow-400.woff2", "Barlow-500.woff2", "Barlow-600.woff2", "Barlow-700.woff2", "BarlowCondensed-600.woff2", "BarlowCondensed-700.woff2", "BarlowCondensed-800.woff2", "icon-180.png", "icon-192.png", "icon-512.png", "icon-maskable-512.png", "splash-1320x2868.png"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// The page itself: try the network first (so updates show at once), fall back to the
// cached copy after 3 seconds or when offline.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  if (e.request.mode === 'navigate') {
    const net = fetch(e.request).then(res => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then(c => c.put('index.html', copy)); }
      return res;
    });
    const slow = new Promise(ok => setTimeout(ok, 3000)).then(() => caches.match('index.html'));
    e.respondWith(Promise.race([net.catch(() => caches.match('index.html')), slow.then(hit => hit || net)])
      .then(r => r || caches.match('index.html')));
    return;
  }
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then(hit => {
    const net = fetch(e.request).then(res => {
      if (res.ok && new URL(e.request.url).origin === location.origin) {
        const copy = res.clone();
        caches.open(CACHE).then(c => c.put(e.request, copy));
      }
      return res;
    }).catch(() => hit || caches.match('index.html'));
    return hit || net;
  }));
});
